#!/usr/bin/env bash
# usage: tests/reference.test.sh      run from anywhere; exits non-zero if docs/reference/scripts.md is stale.
# The page is generated by tests/gen-script-reference.sh from the scripts' header comments. This suite
# asserts the committed page is exactly what the generator prints, and proves the comparison can fail:
# a changed header must make the output differ, and a script with no header, or one that would break
# the code fence, must make the generator refuse.
here=$(cd "$(dirname "$0")" && pwd)
root=$(dirname "$here")
gen=$here/gen-script-reference.sh
fails=0
ok() { echo "PASS  $1"; }
bad() {
  echo "BAD  $1"
  fails=$((fails + 1))
}
T=$(mktemp -d) || exit 1
[ -d "$T" ] || exit 1
fresh() {
  rm -rf "$T/tree"
  mkdir -p "$T/tree"
  cp -R "$root/skills" "$T/tree/"
}
echo "== script reference"
if "$gen" "$root" >"$T/now.md" && cmp -s "$T/now.md" "$root/docs/reference/scripts.md"; then
  ok "the committed page matches the scripts"
else
  bad "docs/reference/scripts.md is stale: run tests/gen-script-reference.sh > docs/reference/scripts.md"
fi
grep -c '^## `' "$T/now.md" | grep -qx "$(find "$root/skills" -path '*/scripts/*.sh' | wc -l | tr -d ' ')" && ok "every shipped script has a section" || bad "section count differs from script count"
fresh
f=$(find "$T/tree/skills" -name check-adrs.sh)
sed -i.bak '2s/$/ EDITED/' "$f" && rm "$f.bak"
if "$gen" "$T/tree" >"$T/edited.md" && ! cmp -s "$T/edited.md" "$root/docs/reference/scripts.md"; then ok "an edited header changes the output"; else bad "an edited header went unnoticed"; fi
fresh
f=$(find "$T/tree/skills" -name check-adrs.sh)
printf '#!/usr/bin/env bash\necho hi\n' >"$f"
if "$gen" "$T/tree" >/dev/null 2>&1; then bad "a script with no header was accepted"; else ok "a script with no header is refused"; fi
fresh
f=$(find "$T/tree/skills" -name check-adrs.sh)
printf '#!/usr/bin/env bash\n# usage: ```\necho hi\n' >"$f"
if "$gen" "$T/tree" >/dev/null 2>&1; then bad "a header with a code fence was accepted"; else ok "a header with a code fence is refused"; fi
rm -rf "$T"
echo "reference failures: $fails"
exit $fails
